import re
import json
from datetime import datetime
from collections import defaultdict, Counter
from typing import Generator

class LogAnalyzer:
 # Nginx/Apache combined log format
 LOG_PATTERN = re.compile(
 r'(?P<ip>\S+) \S+ \S+ \[(?P<time>[^\]]+)\] '
 r'"(?P<method>\S+) (?P<path>\S+) \S+" '
 r'(?P<status>\d{3}) (?P<bytes>\d+|-)'
 r'(?: "(?P<referrer>[^"]*)" "(?P<ua>[^"]*)")?'
)
 ATTACK_PATTERNS = [
 (re.compile(r"'.*(?:OR|AND).*'.*=|--\s*$", re.I), "SQLi"),
 (re.compile(r"<script|javascript:|onerror=", re.I), "XSS"),
 (re.compile(r"\.\./|%2e%2e/", re.I), "Path Traversal"),
 (re.compile(r"wget|curl|bash|/bin/sh|python -c", re.I), "Command Injection"),
 ]

 def __init__(self):
 self.ip_requests = defaultdict(list)
 self.status_codes = Counter()
 self.endpoints = Counter()
 self.attacks = []

 def parse(self, filename: str) -> Generator:
 with open(filename) as f:
 for line in f:
 m = self.LOG_PATTERN.match(line.strip())
 if m: yield m.groupdict()

 def analyse(self, filename: str) -> dict:
 for entry in self.parse(filename):
 ip = entry["ip"]
 status = int(entry["status"])
 path = entry["path"]

 self.ip_requests[ip].append(entry)
 self.status_codes[status] += 1
 self.endpoints[path] += 1

 # Attack pattern detection
 full_req = f"{entry['method']} {path}"
 for pattern, attack_type in self.ATTACK_PATTERNS:
 if pattern.search(path):
 self.attacks.append({
 "ip": ip, "path": path,
 "type": attack_type, "time": entry["time"]
 })

 return self._generate_report()

 def _generate_report(self) -> dict:
 # Brute force detection
 brute_force = {
 ip: len(reqs) for ip, reqs in self.ip_requests.items()
 if len(reqs) > 100
 }
 error_rate = sum(v for k,v in self.status_codes.items() if k >= 400) / max(sum(self.status_codes.values()), 1)
 return {
 "total_requests": sum(self.status_codes.values()),
 "error_rate": f"{error_rate:.1%}",
 "top_ips": dict(Counter({ip: len(r) for ip,r in self.ip_requests.items()}).most_common(5)),
 "brute_force_ips": brute_force,
 "attack_attempts": self.attacks[:20],
 "top_endpoints": dict(self.endpoints.most_common(10)),
 }

if __name__ == "__main__":
 import sys
 analyzer = LogAnalyzer()
 report = analyzer.analyse(sys.argv[1])
 print(json.dumps(report, indent=2))
